-- Isolated test schema, matching the production metadata inspected on 2026-10-19.
create role anon nologin; create role authenticated nologin;
create schema auth; create schema storage;
create function auth.jwt() returns jsonb language sql stable as $$select coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb$$;
create function auth.uid() returns uuid language sql stable as $$select (auth.jwt()->>'sub')::uuid$$;
grant usage on schema auth,storage to authenticated,anon;
create table public.app_users(email text primary key,nom text,role text not null default 'Salarié',actif boolean not null default true,created_at timestamptz not null default now());
create table public.workspace(id text primary key,data jsonb not null default '{}',updated_at timestamptz not null default now(),version bigint not null default 0);
create table public.workspace_backups(id bigint generated by default as identity primary key,created_at timestamptz not null default now(),workspace_id text not null,data jsonb not null,note text);
create table public.messages(id uuid primary key default gen_random_uuid(),channel text not null default 'general',author_email text,author_name text,body text not null,created_at timestamptz not null default now());
create table public.errors(id bigint generated by default as identity primary key,created_at timestamptz not null default now(),user_email text,message text,stack text,page text,user_agent text);
create table storage.objects(id uuid default gen_random_uuid() primary key,bucket_id text,name text,metadata jsonb);
grant all on all tables in schema public,storage to authenticated,anon;
grant usage,select on all sequences in schema public to authenticated,anon;
CREATE OR REPLACE FUNCTION public.zp_gerant()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ select exists(select 1 from app_users where email = lower(coalesce((auth.jwt()->>'email'), '')) and actif and role = 'Gérant') $function$
;
CREATE OR REPLACE FUNCTION public.zp_guard_workspace()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare old_seq int; new_seq int; old_devis int; new_devis int; old_cli int; new_cli int;
begin
  old_seq := coalesce((OLD.data->'scal'->>'_devisSeq')::int,0);
  new_seq := coalesce((NEW.data->'scal'->>'_devisSeq')::int,0);
  old_devis := coalesce(jsonb_array_length(OLD.data->'arr'->'devisDossiers'),0);
  new_devis := coalesce(jsonb_array_length(NEW.data->'arr'->'devisDossiers'),0);
  old_cli := coalesce(jsonb_array_length(OLD.data->'arr'->'clients'),0);
  new_cli := coalesce(jsonb_array_length(NEW.data->'arr'->'clients'),0);
  if new_seq < old_seq - 2 and new_devis < old_devis - 2 then
    raise exception 'ZP_GUARD regression rejetee (seq %/%, devis %/%, clients %/%). Recharge la page (Ctrl+Maj+R) et reessaie.', old_seq,new_seq,old_devis,new_devis,old_cli,new_cli;
  end if;
  return NEW;
end $function$
;
CREATE OR REPLACE FUNCTION public.zp_member()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ select exists(select 1 from app_users where email = lower(coalesce((auth.jwt()->>'email'), '')) and actif) $function$
;
CREATE OR REPLACE FUNCTION public.zp_nightly_snapshot()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ begin insert into public.workspace_backups (workspace_id, data, note) select id, data, 'auto ' || to_char(now() at time zone 'Europe/Paris', 'YYYY-MM-DD') from public.workspace; delete from public.workspace_backups where note like 'auto %' and created_at < now() - interval '30 days'; end $function$
;
CREATE OR REPLACE FUNCTION public.zp_staff()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ select exists( select 1 from app_users
  where email = lower(coalesce((auth.jwt()->>'email'),'')) and actif
  and coalesce(role,'') <> 'Client' ) $function$
;
CREATE OR REPLACE FUNCTION public.zp_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ begin new.updated_at := now(); new.version := coalesce(old.version, 0) + 1; return new; end $function$
;
CREATE TRIGGER trg_workspace_touch BEFORE UPDATE ON public.workspace FOR EACH ROW EXECUTE FUNCTION zp_touch_updated_at();
CREATE TRIGGER trg_zp_guard BEFORE UPDATE ON public.workspace FOR EACH ROW EXECUTE FUNCTION zp_guard_workspace();
alter table public.workspace enable row level security;
alter table public.messages enable row level security;
alter table public.errors enable row level security;
alter table public.workspace_backups enable row level security;
alter table public.app_users enable row level security;
alter table storage.objects enable row level security;
create policy ws_update on public.workspace for UPDATE to authenticated using (zp_staff()) with check (zp_staff());
create policy ws_insert on public.workspace for INSERT to authenticated with check (zp_staff());
create policy ws_select on public.workspace for SELECT to authenticated using (zp_staff());
create policy msg_insert on public.messages for INSERT to authenticated with check (zp_staff());
create policy msg_select on public.messages for SELECT to authenticated using (zp_staff());
create policy errors_insert_auth on public.errors for INSERT to authenticated with check (zp_member());
create policy errors_select_auth on public.errors for SELECT to authenticated using (zp_gerant());
create policy wb_all_auth on public.workspace_backups for ALL to authenticated using (zp_staff()) with check (zp_staff());
create policy au_delete on public.app_users for DELETE to authenticated using (zp_gerant());
create policy au_update on public.app_users for UPDATE to authenticated using (zp_gerant()) with check (zp_gerant());
create policy au_insert on public.app_users for INSERT to authenticated with check (zp_gerant());
create policy au_select on public.app_users for SELECT to authenticated using (zp_member());
create policy zpfiles_delete on storage.objects for DELETE to authenticated using (((bucket_id = 'zp-files'::text) AND zp_gerant()));
create policy zpfiles_update on storage.objects for UPDATE to authenticated using (((bucket_id = 'zp-files'::text) AND zp_staff())) with check (((bucket_id = 'zp-files'::text) AND zp_staff()));
create policy zpfiles_insert on storage.objects for INSERT to authenticated with check (((bucket_id = 'zp-files'::text) AND zp_staff()));
create policy zpfiles_select on storage.objects for SELECT to authenticated using (((bucket_id = 'zp-files'::text) AND zp_staff()));
